// Linear scan -- at most 42 entries in this project's whole write registry (far smaller
// than kFields' own ~155-entry scan in jk_poll_scheduler_core.h's find_block_index_for_
// address, already accepted there for the same reason: this only runs on an actual write
// or preflight request, never on a hot poll-scheduler path.
inline int find_entry_index(const char *key) {
  for (std::size_t i = 0; i < kEntryCount; i++) {
    if (std::strcmp(kEntries[i].key, key) == 0) return int(i);
  }
  return -1;
}

